{"command":"cd ./workspace
$ib = [System.IO.File]::ReadAllBytes((Resolve-Path '.git\index'))
$cnt = [System.Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($ib,8))
$idx = @{}
$pos = 12
for ($e=0; $e -lt $cnt; $e++) {
  $start = $pos
  $shaHex = ([BitConverter]::ToString($ib, $pos+40, 20)).Replace('-','').ToLower()
  $flags = [System.Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt16($ib, $pos+60))
  $nameLen = $flags -band 0x0FFF
  $pathStart = $pos + 62
  if (($flags -band 0x4000) -ne 0) { $pathStart += 2 }
  if ($nameLen -eq 0x0FFF) { $end = [Array]::IndexOf($ib, [byte]0, $pathStart); $len = $end - $pathStart } else { $len = $nameLen }
  $pname = [Text.Encoding]::ASCII.GetString($ib, $pathStart, $len)
  $idx[$pname] = $shaHex
  $entryLen = $pathStart - $pos + $len + 1
  $pos = $start + ([Math]::Ceiling($entryLen / 8.0) * 8)
}
$sha1 = [System.Security.Cryptography.SHA1]::Create()
$changed = @(); $missing = @()
foreach ($k in $idx.Keys) {
  $full = Join-Path (Resolve-Path .).Path ($k -replace '/','\')
  if (-not (Test-Path -LiteralPath $full)) { $missing += $k; continue }
  $fb = [System.IO.File]::ReadAllBytes($full)
  $prefix = [Text.Encoding]::ASCII.GetBytes("blob $($fb.Length)`0")
  $ms = New-Object System.IO.MemoryStream
  $ms.Write($prefix,0,$prefix.Length); $ms.Write($fb,0,$fb.Length)
  $h = ([BitConverter]::ToString($sha1.ComputeHash($ms.ToArray()))).Replace('-','').ToLower()
  $ms.Dispose()
  if ($h -ne $idx[$k]) { $changed += $k }
}
Write-Output "total tracked (index)=$($idx.Count)"
Write-Output "changed vs index=$($changed.Count)"
Write-Output "missing vs index=$($missing.Count)"
if ($changed.Count -gt 0) { Write-Output "CHANGED:"; $changed | Sort-Object }
if ($missing.Count -gt 0) { Write-Output "MISSING:"; $missing | Sort-Object }
Write-Output "===""}

