{"command":"cd ./workspace
# ---------- pack loader ----------
$gitRoot = (Resolve-Path .).Path
$packDir = Join-Path $gitRoot '.git\objects\pack'
$packFile = Get-ChildItem $packDir -Filter *.pack | Select-Object -First 1
$idxFile = Get-ChildItem $packDir -Filter *.idx | Select-Object -First 1
$pb = [System.IO.File]::ReadAllBytes($packFile.FullName)
$idxBytes = [System.IO.File]::ReadAllBytes($idxFile.FullName)
$N = [System.Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($idxBytes, 8 + 1024))
$shaTableStart = 8 + 1024
$offTableStart = $shaTableStart + 20*$N + 4*$N
$offBySha = @{}
for ($k=0; $k -lt $N; $k++) {
  $sha = ([BitConverter]::ToString($idxBytes, $shaTableStart + $k*20, 20)).Replace('-','').ToLower()
  $off = [System.Net.IPAddress]::NetworkToHostOrder([BitConverter]::ToInt32($idxBytes, $offTableStart + $k*4))
  $offBySha[$sha] = $off
}
function Read-VarInt([byte[]]$data, [ref]$p) {
  $val = 0; $shift = 0
  while ($true) { $b = $data[$p.Value]; $p.Value++; $val = $val -bor (($b -band 0x7f) -shl $shift); if (($b -band 0x80) -eq 0) { break }; $shift += 7 }
  return $val
}
$memGetObj = @{}
function Get-Obj([string]$sha) {
  if ($memGetObj.ContainsKey($sha)) { return $memGetObj[$sha] }
  $p = Join-Path $gitRoot ('.git\objects\' + $sha.Substring(0,2) + '\' + $sha.Substring(2))
  $body = $null
  if (Test-Path -LiteralPath $p) {
    $bytes = [System.IO.File]::ReadAllBytes($p)
    $ms = New-Object System.IO.MemoryStream (,$bytes); $ms.Position = 2
    $ds = New-Object System.IO.Compression.DeflateStream ($ms, [System.IO.Compression.CompressionMode]::Decompress)
    $out = New-Object System.IO.MemoryStream; $ds.CopyTo($out)
    $raw = $out.ToArray()
    $nul = [Array]::IndexOf($raw, [byte]0)
    $body = New-Object byte[] ($raw.Length - $nul - 1)
    [Array]::Copy($raw, $nul+1, $body, 0, $body.Length)
    $ds.Dispose(); $ms.Dispose(); $out.Dispose()
  } else {
    $body = Read-PackObject ($offBySha[$sha])
  }
  $mem
